import { IEstado } from './estado.model';
import { Materia } from './materia.model';

export class RegistroAcademico {
  constructor(
    public materia: Materia,
    public cuatrimestre: string,
    public nota: number,
    public estado: IEstado,
  ) {}

  estaAprobada(): boolean {
    return this.estado.estaAprobada();
  }

  getNota(): number {
    return this.nota;
  }

  getMateria(): Materia {
    return this.materia;
  }
}
